{%- for item in items %}


  {{ item.title }}


    <p>{{ item.caption }}</p>
    {%- if let Some(description) = item.description %}<p>{{ description }}</p>{%- endif %}
    {%- if let Some(text) = item.text %}<p>Текст с картинки: {{ text }}</p>{%- endif %}
    {%- if let Some(source) = item.source %}<p>Источник: {{ source }}</p>{%- endif %}


  https://memexpert.net/{{ item.language }}/{{ item.slug }}
  https://memexpert.net/{{ item.language }}/{{ item.slug }}
  {{ item.pub_date }}

  {%- if item.is_mime_video %}


    {{ item.title }}
    {{ item.caption }}


  {%- else %}


    {{ item.title }}
    {{ item.caption }}

  {%- endif %}

{%- endfor %}
